# Fix: cgroup v2 PSI stall-utilization sampling (key=value parsing, per-sample clock, honest regression handling)

## Root-cause analysis

The original collector had three independent defects that compound into a spurious throttle:

1. **Positional field parsing.** PSI lines are `some avg10=… avg60=… avg300=… total=…` and `full …`. Reading fixed column indices means any field reorder (`total` first) or any added field (`avg1000=…`) silently shifts what is read as `total`. The fix must parse `key=value` by key and keep unknown fields.

2. **One shared timestamp for the whole read loop.** The wall time was captured once before iterating cgroups, then reused for every file. Each counter delta was therefore divided by a wall delta that did not correspond to when that particular file was read. Across multiple cgroups the fabricated `delta_total / delta_wall` can exceed 1.0 and trip the admission throttle. The fix is a per-file timestamp obtained from an injectable `Clock`.

3. **No honest handling of counter regression, missing files, or clamping.** PSI counters reset to 0 when a cgroup is recreated. Subtracting across a reset produced a huge/negative ratio. Missing `*.pressure` files and clamping to 1.0 happened silently, so operators could not tell a real stall from a reset or a missing file.

Correctness contract:

```
raw     = (total_now - total_prev) / ((wall_now - wall_prev) in microseconds)
clamped = clamp(raw, 0, 1)   // consumed by the throttle
reason  = "" | counter_reset | missing_pressure | ratio_above_one | ...
```

`raw` is **always** emitted unmodified; clamping is explicit and carries a reason. `NaN`/`Inf` are impossible because division only occurs after `delta_wall > 0`.

## The fix

Source below is verified with Go 1.26 (`go vet`, `go test`, `go test -race` all clean).

```
psistall/
├── go.mod
├── psi.go
├── collector.go
└── collector_test.go
```

### `go.mod`

```go
module psistall

go 1.26
```

### `psi.go` — order-independent parser + result types

```go
// Package psistall samples cgroup v2 PSI (Pressure Stall Information)
// counters and turns them into a stall-utilization ratio.
//
// Design constraints this package is built around:
//
//  1. PSI fields MUST be parsed by key=value, never by column index. Kernel
//     versions and future kernels may emit avg10/avg60/avg300/total in any
//     order, may add fields, and may emit the "some"/"full" lines in any
//     order.
//  2. Every pressure file is stamped with its own wall-clock time obtained
//     from an injected Clock. A single timestamp shared across a read loop
//     fabricates deltas when more than one cgroup is sampled.
//  3. Counters can regress (PSI counters reset when a cgroup is recreated).
//     That is reported, never hidden as a huge or negative ratio.
//  4. The raw ratio is always reported next to a clamped ratio and the
//     reason it was clamped, so a throttle never acts on a silently
//     saturated value.
package psistall

import (
	"bufio"
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// Line identifies a PSI summary line.
type Line string

const (
	LineSome Line = "some"
	LineFull Line = "full"
)

// LineValues holds one parsed PSI summary line. Unknown future fields are
// preserved in Extra rather than discarded.
type LineValues struct {
	Avg10    float64
	Avg60    float64
	Avg300   float64
	Total    uint64
	HasTotal bool
	Extra    map[string]float64
}

// Pressure is the parsed content of a cpu.pressure / memory.pressure /
// io.pressure file.
type Pressure struct {
	Lines map[Line]LineValues
}

// ParsePressure parses a PSI file strictly by key=value. It never relies on
// field position, tolerates extra/unknown fields, and tolerates the "total"
// field appearing before or after the averages.
func ParsePressure(data []byte) (Pressure, error) {
	p := Pressure{Lines: make(map[Line]LineValues)}

	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)

	for sc.Scan() {
		raw := strings.TrimSpace(sc.Text())
		if raw == "" {
			continue
		}
		fields := strings.Fields(raw)
		name := Line(fields[0])
		if name != LineSome && name != LineFull {
			// Unknown summary line: ignore, do not guess at its layout.
			continue
		}

		lv := LineValues{Extra: make(map[string]float64)}
		for _, f := range fields[1:] {
			k, v, ok := strings.Cut(f, "=")
			if !ok {
				return p, fmt.Errorf("psistall: malformed field %q in %q line", f, name)
			}
			switch k {
			case "avg10":
				x, err := strconv.ParseFloat(v, 64)
				if err != nil {
					return p, fmt.Errorf("psistall: %s avg10: %w", name, err)
				}
				lv.Avg10 = x
			case "avg60":
				x, err := strconv.ParseFloat(v, 64)
				if err != nil {
					return p, fmt.Errorf("psistall: %s avg60: %w", name, err)
				}
				lv.Avg60 = x
			case "avg300":
				x, err := strconv.ParseFloat(v, 64)
				if err != nil {
					return p, fmt.Errorf("psistall: %s avg300: %w", name, err)
				}
				lv.Avg300 = x
			case "total":
				u, err := parseTotal(v)
				if err != nil {
					return p, fmt.Errorf("psistall: %s total: %w", name, err)
				}
				lv.Total = u
				lv.HasTotal = true
			default:
				x, err := strconv.ParseFloat(v, 64)
				if err != nil {
					return p, fmt.Errorf("psistall: %s %s: %w", name, k, err)
				}
				lv.Extra[k] = x
			}
		}
		p.Lines[name] = lv
	}
	if err := sc.Err(); err != nil {
		return p, err
	}
	return p, nil
}

func parseTotal(v string) (uint64, error) {
	if u, err := strconv.ParseUint(v, 10, 64); err == nil {
		return u, nil
	}
	f, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return 0, err
	}
	if f < 0 {
		return 0, fmt.Errorf("negative total %q", v)
	}
	return uint64(f), nil
}

// Clamp reasons emitted on Utilization.Reason.
const (
	ReasonNone            = ""
	ReasonFirstSample     = "first_sample"
	ReasonCounterReset    = "counter_reset"
	ReasonMissingPressure = "missing_pressure"
	ReasonTotalMissing    = "total_field_missing"
	ReasonNonPositiveWall = "non_positive_wall_delta"
	ReasonRatioAboveOne   = "ratio_above_one"
	ReasonRatioBelowZero  = "ratio_below_zero"
	ReasonReadError       = "read_error"
	ReasonParseError      = "parse_error"
)

// Utilization is the computed ratio for one (cgroup, pressure kind, PSI
// line). Raw is always the honest delta_total/delta_wall value; Clamped is
// the value a throttle should consume and Reason explains any clamping.
type Utilization struct {
	Cgroup string
	Kind   Kind
	Line   Line
	Wall   time.Time

	DeltaTotal uint64
	DeltaWall  time.Duration

	Raw     float64
	Clamped float64
	Reason  string
	Valid   bool
	Missing bool
}
```

### `collector.go` — per-sample timestamp, regression + missing handling

```go
package psistall

import (
	"errors"
	"os"
	"path/filepath"
	"time"
)

// Kind identifies which cgroup v2 pressure file is sampled.
type Kind string

const (
	KindCPU    Kind = "cpu"
	KindMemory Kind = "memory"
	KindIO     Kind = "io"
)

// defaultKinds is the fixed set sampled for every cgroup.
var defaultKinds = []Kind{KindCPU, KindMemory, KindIO}

// Clock is the injectable wall-clock source. Real callers pass nil (or
// systemClock{}); tests inject a deterministic, advancing clock.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

type prevKey struct {
	Cgroup string
	Kind   Kind
	Line   Line
}

type prevSample struct {
	Total uint64
	Wall  time.Time
}

// Collector samples a fixture or real sysfs root. It keeps the previous
// counter + wall time for every (cgroup, kind, line) it has seen.
type Collector struct {
	root  string
	clock Clock
	prev  map[prevKey]prevSample
}

// New returns a Collector rooted at root. If clock is nil, time.Now is used.
func New(root string, clock Clock) *Collector {
	if clock == nil {
		clock = systemClock{}
	}
	return &Collector{
		root:  root,
		clock: clock,
		prev:  make(map[prevKey]prevSample),
	}
}

// Reset drops all previous counters, e.g. after a configuration reload.
func (c *Collector) Reset() {
	c.prev = make(map[prevKey]prevSample)
}

// Collect samples every pressure file of every cgroup in order and returns
// one Utilization per (cgroup, kind, PSI line).
func (c *Collector) Collect(cgroups []string) []Utilization {
	var out []Utilization
	for _, cg := range cgroups {
		for _, kind := range defaultKinds {
			out = append(out, c.collectKind(cg, kind)...)
		}
	}
	return out
}

func (c *Collector) collectKind(cgroup string, kind Kind) []Utilization {
	// Key fix: the wall timestamp belongs to THIS pressure file. It is not
	// captured once outside the loop (which would mis-stamp every cgroup).
	wall := c.clock.Now()

	path := filepath.Join(c.root, cgroup, string(kind)+".pressure")
	data, err := os.ReadFile(path)
	if err != nil {
		reason := ReasonReadError
		missing := false
		if errors.Is(err, os.ErrNotExist) {
			reason = ReasonMissingPressure
			missing = true
		}
		// Emit one result per PSI line so callers always see the same key
		// shape, even when the file is absent.
		out := make([]Utilization, 0, 2)
		for _, ln := range []Line{LineSome, LineFull} {
			out = append(out, Utilization{
				Cgroup:  cgroup,
				Kind:    kind,
				Line:    ln,
				Wall:    wall,
				Reason:  reason,
				Missing: missing,
			})
		}
		return out
	}

	p, perr := ParsePressure(data)

	out := make([]Utilization, 0, 2)
	for _, ln := range []Line{LineSome, LineFull} {
		lv, ok := p.Lines[ln]
		out = append(out, c.observe(cgroup, kind, ln, wall, lv, ok, perr))
	}
	return out
}

func (c *Collector) observe(
	cgroup string, kind Kind, line Line, wall time.Time,
	lv LineValues, hasLine bool, parseErr error,
) Utilization {
	u := Utilization{Cgroup: cgroup, Kind: kind, Line: line, Wall: wall}

	if parseErr != nil {
		u.Reason = ReasonParseError
		return u
	}
	if !hasLine || !lv.HasTotal {
		u.Reason = ReasonTotalMissing
		return u
	}

	key := prevKey{Cgroup: cgroup, Kind: kind, Line: line}
	prev, seen := c.prev[key]
	// Always move the baseline forward, including after a reset, so the
	// next interval is measurable again.
	c.prev[key] = prevSample{Total: lv.Total, Wall: wall}

	if !seen {
		u.Reason = ReasonFirstSample
		return u
	}

	dw := wall.Sub(prev.Wall)
	u.DeltaWall = dw

	// Counter regression: PSI counters reset when a cgroup is recreated.
	// Report it honestly instead of emitting a negative/huge ratio.
	if lv.Total < prev.Total {
		u.Reason = ReasonCounterReset
		u.Raw = 0
		u.Clamped = 0
		return u
	}

	dt := lv.Total - prev.Total
	u.DeltaTotal = dt

	if dw <= 0 {
		u.Reason = ReasonNonPositiveWall
		u.Raw = 0
		u.Clamped = 0
		return u
	}

	// total is microseconds; convert wall to microseconds to keep the ratio
	// dimensionless. delta_total / delta_wall_us.
	wallUs := float64(dw) / float64(time.Microsecond)
	raw := float64(dt) / wallUs

	u.Raw = raw
	u.Valid = true

	// Raw is preserved; clamping is explicit and carries a reason.
	switch {
	case raw > 1:
		u.Clamped = 1
		u.Reason = ReasonRatioAboveOne
	case raw < 0:
		u.Clamped = 0
		u.Reason = ReasonRatioBelowZero
	default:
		u.Clamped = raw
		u.Reason = ReasonNone
	}
	return u
}
```

### `collector_test.go` — fixture sysfs table tests

```go
package psistall

import (
	"math"
	"os"
	"path/filepath"
	"strconv"
	"testing"
	"time"
)

// stepClock advances by a fixed step on every Now() call, so a test can
// predict the exact wall delta between two samples of the same file.
type stepClock struct {
	now  time.Time
	step time.Duration
}

func newStepClock(step time.Duration) *stepClock {
	return &stepClock{now: time.Unix(1_700_000_000, 0), step: step}
}

func (c *stepClock) Now() time.Time {
	t := c.now
	c.now = c.now.Add(c.step)
	return t
}

func writeFiles(t *testing.T, root string, files map[string]string) {
	t.Helper()
	for rel, content := range files {
		p := filepath.Join(root, rel)
		if content == "" {
			if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
				t.Fatalf("remove %s: %v", p, err)
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", filepath.Dir(p), err)
		}
		if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
			t.Fatalf("write %s: %v", p, err)
		}
	}
}

// psiDoc builds a two-line PSI file. order is "avg-first" or "total-first";
// extra appends an unknown field to prove added fields are tolerated.
func psiDoc(someTotal, fullTotal uint64, order string, extra bool) string {
	line := func(name string, total uint64) string {
		avg := "avg10=0.50 avg60=0.25 avg300=0.10"
		if extra {
			avg += " avg1000=0.00"
		}
		tf := "total=" + strconv.FormatUint(total, 10)
		if order == "total-first" {
			return name + " " + tf + " " + avg
		}
		return name + " " + avg + " " + tf
	}
	return line("some", someTotal) + "\n" + line("full", fullTotal) + "\n"
}

func resultKey(u Utilization) string {
	return u.Cgroup + "/" + string(u.Kind) + "/" + string(u.Line)
}

func findByKey(t *testing.T, us []Utilization, key string) Utilization {
	t.Helper()
	for _, u := range us {
		if resultKey(u) == key {
			return u
		}
	}
	t.Fatalf("no result for %s", key)
	return Utilization{}
}

// checkInvariants enforces the hard guarantees for every emitted result:
// no NaN/Inf, and every valid ratio equals delta_total/delta_wall_us to
// within 1e-9.
func checkInvariants(t *testing.T, all [][]Utilization) {
	t.Helper()
	for i, us := range all {
		for _, u := range us {
			if math.IsNaN(u.Raw) || math.IsInf(u.Raw, 0) {
				t.Fatalf("interval %d %s: Raw not finite: %v", i, resultKey(u), u.Raw)
			}
			if math.IsNaN(u.Clamped) || math.IsInf(u.Clamped, 0) {
				t.Fatalf("interval %d %s: Clamped not finite: %v", i, resultKey(u), u.Clamped)
			}
			if !u.Valid {
				continue
			}
			wallUs := float64(u.DeltaWall) / float64(time.Microsecond)
			if wallUs <= 0 {
				t.Fatalf("interval %d %s: valid with wallUs=%v", i, resultKey(u), wallUs)
			}
			want := float64(u.DeltaTotal) / wallUs
			if math.Abs(u.Raw-want) > 1e-9 {
				t.Fatalf("interval %d %s: Raw=%v want=%v (diff=%g)",
					i, resultKey(u), u.Raw, want, math.Abs(u.Raw-want))
			}
			if u.Clamped < 0 || u.Clamped > 1 {
				t.Fatalf("interval %d %s: clamped out of range: %v", i, resultKey(u), u.Clamped)
			}
			if u.Reason == ReasonRatioAboveOne && u.Clamped != 1 {
				t.Fatalf("interval %d %s: above-one reason but clamp=%v", i, resultKey(u), u.Clamped)
			}
			if u.Reason == ReasonNone && u.Clamped != u.Raw {
				t.Fatalf("interval %d %s: unclamped value changed: raw=%v clamped=%v",
					i, resultKey(u), u.Raw, u.Clamped)
			}
		}
	}
}

func TestCollectorTable(t *testing.T) {
	const step = 100 * time.Millisecond

	cases := []struct {
		name      string
		cgroups   []string
		snapshots []map[string]string
		check     func(t *testing.T, all [][]Utilization)
	}{
		{
			name:    "reordered_and_added_fields_two_cgroups",
			cgroups: []string{"cg1", "cg2"},
			snapshots: []map[string]string{
				{
					"cg1/cpu.pressure":    psiDoc(100000, 200000, "avg-first", false),
					"cg1/memory.pressure": psiDoc(10000, 20000, "avg-first", false),
					"cg1/io.pressure":     psiDoc(0, 0, "avg-first", false),
					"cg2/cpu.pressure":    psiDoc(50000, 60000, "avg-first", false),
					"cg2/memory.pressure": psiDoc(1000, 2000, "avg-first", false),
					"cg2/io.pressure":     psiDoc(4000, 5000, "avg-first", false),
				},
				{
					// Second interval: total-first, plus an extra field.
					"cg1/cpu.pressure":    psiDoc(400000, 800000, "total-first", true),
					"cg1/memory.pressure": psiDoc(40000, 50000, "total-first", true),
					"cg1/io.pressure":     psiDoc(0, 0, "total-first", true),
					"cg2/cpu.pressure":    psiDoc(65000, 66000, "total-first", true),
					"cg2/memory.pressure": psiDoc(1000, 2000, "total-first", true),
					"cg2/io.pressure":     psiDoc(30000, 31000, "total-first", true),
				},
			},
			check: func(t *testing.T, all [][]Utilization) {
				last := all[len(all)-1]
				// 2 cgroups * 3 kinds * 100ms per Now() call = 600ms wall delta.
				const wallUs = 600000.0
				expect := map[string]float64{
					"cg1/cpu/some":    300000 / wallUs,
					"cg1/cpu/full":    600000 / wallUs,
					"cg1/memory/some": 30000 / wallUs,
					"cg1/memory/full": 30000 / wallUs,
					"cg1/io/some":     0,
					"cg1/io/full":     0,
					"cg2/cpu/some":    15000 / wallUs,
					"cg2/cpu/full":    6000 / wallUs,
					"cg2/memory/some": 0,
					"cg2/memory/full": 0,
					"cg2/io/some":     26000 / wallUs,
					"cg2/io/full":     26000 / wallUs,
				}
				for key, want := range expect {
					u := findByKey(t, last, key)
					if !u.Valid {
						t.Fatalf("%s: not valid, reason=%q", key, u.Reason)
					}
					if math.Abs(u.Raw-want) > 1e-9 {
						t.Fatalf("%s: raw=%v want=%v", key, u.Raw, want)
					}
					if u.Clamped != u.Raw {
						t.Fatalf("%s: expected no clamp, raw=%v clamped=%v", key, u.Raw, u.Clamped)
					}
				}
				// The averages must have been parsed by key, not ignored.
				if u := findByKey(t, last, "cg1/cpu/some"); u.Wall.IsZero() {
					t.Fatalf("wall timestamp not set")
				}
			},
		},
		{
			name:    "counter_reset_then_recovery",
			cgroups: []string{"cg1"},
			snapshots: []map[string]string{
				{
					"cg1/cpu.pressure":    psiDoc(900000, 900000, "avg-first", false),
					"cg1/memory.pressure": psiDoc(1000, 1000, "avg-first", false),
					"cg1/io.pressure":     psiDoc(2000, 2000, "avg-first", false),
				},
				{
					// Counter regression: cgroup was recreated.
					"cg1/cpu.pressure":    psiDoc(100000, 100000, "avg-first", false),
					"cg1/memory.pressure": psiDoc(1000, 1000, "avg-first", false),
					"cg1/io.pressure":     psiDoc(2000, 2000, "avg-first", false),
				},
				{
					// Recovery: baseline is the post-reset value.
					"cg1/cpu.pressure":    psiDoc(250000, 250000, "avg-first", false),
					"cg1/memory.pressure": psiDoc(1000, 1000, "avg-first", false),
					"cg1/io.pressure":     psiDoc(2000, 2000, "avg-first", false),
				},
			},
			check: func(t *testing.T, all [][]Utilization) {
				const wallUs = 300000.0 // 1 cgroup * 3 kinds * 100ms

				reset := findByKey(t, all[1], "cg1/cpu/some")
				if reset.Reason != ReasonCounterReset {
					t.Fatalf("reset: reason=%q, want %q", reset.Reason, ReasonCounterReset)
				}
				if reset.Valid {
					t.Fatalf("reset must not be reported as valid")
				}
				if reset.Raw != 0 || reset.Clamped != 0 {
					t.Fatalf("reset: raw=%v clamped=%v, want 0/0", reset.Raw, reset.Clamped)
				}

				recovered := findByKey(t, all[2], "cg1/cpu/some")
				if !recovered.Valid {
					t.Fatalf("recovered: not valid, reason=%q", recovered.Reason)
				}
				const want = 150000 / wallUs
				if math.Abs(recovered.Raw-want) > 1e-9 {
					t.Fatalf("recovered raw=%v want=%v", recovered.Raw, want)
				}
			},
		},
		{
			name:    "missing_io_pressure",
			cgroups: []string{"cg1"},
			snapshots: []map[string]string{
				{
					"cg1/cpu.pressure":    psiDoc(0, 0, "avg-first", false),
					"cg1/memory.pressure": psiDoc(0, 0, "avg-first", false),
					// io.pressure intentionally omitted
				},
				{
					"cg1/cpu.pressure":    psiDoc(150000, 150000, "avg-first", false),
					"cg1/memory.pressure": psiDoc(150000, 150000, "avg-first", false),
				},
			},
			check: func(t *testing.T, all [][]Utilization) {
				for _, iv := range all {
					for _, key := range []string{"cg1/io/some", "cg1/io/full"} {
						u := findByKey(t, iv, key)
						if !u.Missing || u.Reason != ReasonMissingPressure {
							t.Fatalf("%s: missing=%v reason=%q", key, u.Missing, u.Reason)
						}
					}
				}
				// cpu/memory still work.
				u := findByKey(t, all[1], "cg1/cpu/some")
				if !u.Valid || u.Raw != 0.5 {
					t.Fatalf("cpu: valid=%v raw=%v want 0.5", u.Valid, u.Raw)
				}
			},
		},
		{
			name:    "ratio_above_one_is_raw_plus_clamped_with_reason",
			cgroups: []string{"cg1"},
			snapshots: []map[string]string{
				{"cg1/cpu.pressure": psiDoc(0, 0, "avg-first", false)},
				{"cg1/cpu.pressure": psiDoc(900000, 900000, "avg-first", false)},
			},
			check: func(t *testing.T, all [][]Utilization) {
				u := findByKey(t, all[1], "cg1/cpu/some")
				if !u.Valid {
					t.Fatalf("not valid: reason=%q", u.Reason)
				}
				const want = 900000 / 300000.0 // = 3.0
				if math.Abs(u.Raw-want) > 1e-9 {
					t.Fatalf("raw=%v want=%v", u.Raw, want)
				}
				if u.Reason != ReasonRatioAboveOne {
					t.Fatalf("reason=%q, want %q", u.Reason, ReasonRatioAboveOne)
				}
				if u.Clamped != 1 {
					t.Fatalf("clamped=%v, want 1", u.Clamped)
				}
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := t.TempDir()
			clock := newStepClock(step)
			col := New(root, clock)

			var all [][]Utilization
			for _, snap := range tc.snapshots {
				writeFiles(t, root, snap)
				all = append(all, col.Collect(tc.cgroups))
			}

			checkInvariants(t, all)
			tc.check(t, all)
		})
	}
}

// TestParsePressureKeyOrder proves the parser is positional-independent and
// preserves unknown fields.
func TestParsePressureKeyOrder(t *testing.T) {
	avgFirst := "some avg10=1.00 avg60=2.00 avg300=3.00 total=111\nfull avg10=4.00 avg60=5.00 avg300=6.00 total=222\n"
	totalFirst := "full total=222 avg10=4.00 avg60=5.00 avg300=6.00 avg999=7.00\nsome total=111 avg10=1.00 avg60=2.00 avg300=3.00 avg999=7.00\n"

	for name, data := range map[string]string{"avg-first": avgFirst, "total-first": totalFirst} {
		t.Run(name, func(t *testing.T) {
			p, err := ParsePressure([]byte(data))
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			some := p.Lines[LineSome]
			full := p.Lines[LineFull]
			if !some.HasTotal || some.Total != 111 {
				t.Fatalf("some total=%d has=%v, want 111", some.Total, some.HasTotal)
			}
			if !full.HasTotal || full.Total != 222 {
				t.Fatalf("full total=%d has=%v, want 222", full.Total, full.HasTotal)
			}
			if some.Avg10 != 1 || some.Avg60 != 2 || some.Avg300 != 3 {
				t.Fatalf("some averages parsed wrong: %+v", some)
			}
			if name == "total-first" {
				if got := some.Extra["avg999"]; got != 7 {
					t.Fatalf("extra field not preserved: %v", got)
				}
			}
		})
	}
}

// TestPerSampleTimestamp ensures each pressure file gets its own timestamp
// from the injected clock rather than one shared pre-loop timestamp.
func TestPerSampleTimestamp(t *testing.T) {
	root := t.TempDir()
	writeFiles(t, root, map[string]string{
		"cg1/cpu.pressure":    psiDoc(0, 0, "avg-first", false),
		"cg1/memory.pressure": psiDoc(0, 0, "avg-first", false),
		"cg1/io.pressure":     psiDoc(0, 0, "avg-first", false),
		"cg2/cpu.pressure":    psiDoc(0, 0, "avg-first", false),
		"cg2/memory.pressure": psiDoc(0, 0, "avg-first", false),
		"cg2/io.pressure":     psiDoc(0, 0, "avg-first", false),
	})

	clock := newStepClock(10 * time.Millisecond)
	col := New(root, clock)
	got := col.Collect([]string{"cg1", "cg2"})

	// Six files => six distinct timestamps. The some/full lines of one file
	// legitimately share the file's timestamp.
	fileWall := map[string]time.Time{}
	for _, u := range got {
		file := u.Cgroup + "/" + string(u.Kind)
		if prev, ok := fileWall[file]; ok && !prev.Equal(u.Wall) {
			t.Fatalf("%s: some/full lines of one file have different stamps", file)
		}
		fileWall[file] = u.Wall
	}
	if len(fileWall) != 6 {
		t.Fatalf("got %d files, want 6", len(fileWall))
	}
	seen := map[time.Time]bool{}
	for _, w := range fileWall {
		if seen[w] {
			t.Fatalf("duplicate wall timestamp %v: timestamp was shared across files", w)
		}
		seen[w] = true
	}
}
